import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import TOHaejungTable from '@/components/TOHaejungTable';
import type { ToHaejungRow } from '@/lib/types';

const mockRows: ToHaejungRow[] = [
  {
    id: 1,
    college: '문과대학',
    department: '국어국문학과',
    confirm_rate_26: '62.1%',
    faculty_count_26: '14',
    new_hires: '이혜령',
    retirees: null,
    upcoming_retirements: '권인한, 정우택',
    req_general: '2',
    req_dedicated: null,
    req_external: null,
    req_total: '2',
    invitation_field: '디지털인문학',
    request_reason: 'AI 시대 대응',
    to_general: '1',
    to_dedicated: null,
    to_external: null,
    to_total: '1',
    adv_general: null,
    adv_dedicated: null,
    adv_external: null,
    adv_total: null,
    pres_general: null,
    pres_dedicated: null,
    pres_external: null,
    pres_total: null,
    assign_reason: null,
    hq_opinion: '미참여',
    bigs: '미참여',
    to_req_25: '2',
    to_assign_25: '1',
    hire_regular_25: '0',
    hire_rolling_25: '0',
    hire_total_25: '0',
    note: null,
    remark: null,
    created_at: null,
    updated_at: null,
  },
];

describe('TOHaejungTable', () => {
  it('renders table with row data', () => {
    render(<TOHaejungTable rows={mockRows} />);
    expect(screen.getByText('국어국문학과')).toBeInTheDocument();
    expect(screen.getByText('문과대학')).toBeInTheDocument();
  });

  it('shows all column group headers', () => {
    render(<TOHaejungTable rows={mockRows} />);
    expect(screen.getByText('소속대학')).toBeInTheDocument();
    expect(screen.getByText('학과명')).toBeInTheDocument();
    expect(screen.getByText(/일반TO 배정/)).toBeInTheDocument();
  });

  it('renders empty state when no rows', () => {
    render(<TOHaejungTable rows={[]} />);
    expect(screen.getByText(/데이터가 없습니다/)).toBeInTheDocument();
  });

  it('calls onSave on cell double-click and Enter in editable mode', async () => {
    const onSave = jest.fn().mockResolvedValue(undefined);
    render(<TOHaejungTable rows={mockRows} editable onSave={onSave} />);
    const cell = screen.getByText('국어국문학과');
    fireEvent.doubleClick(cell);
    const input = screen.getByDisplayValue('국어국문학과');
    fireEvent.change(input, { target: { value: '새학과명' } });
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(onSave).toHaveBeenCalledWith(1, { department: '새학과명' });
  });
});

'use client';

import React, { useState, useCallback, useRef, useEffect } from 'react';
import type { ToHaejungRow } from '@/lib/types';

interface TOHaejungTableProps {
  rows: ToHaejungRow[];
  editable?: boolean;
  onSave?: (id: number, fields: Record<string, string>) => Promise<void>;
}

const FIELD_KEYS: (keyof ToHaejungRow)[] = [
  'college', 'department', 'confirm_rate_26', 'faculty_count_26',
  'new_hires', 'retirees', 'upcoming_retirements',
  'req_general', 'req_dedicated', 'req_external', 'req_total',
  'invitation_field', 'request_reason',
  'to_general', 'to_dedicated', 'to_external', 'to_total',
  'adv_general', 'adv_dedicated', 'adv_external', 'adv_total',
  'pres_general', 'pres_dedicated', 'pres_external', 'pres_total',
  'assign_reason', 'hq_opinion', 'bigs',
  'to_req_25', 'to_assign_25',
  'hire_regular_25', 'hire_rolling_25', 'hire_total_25',
  'note', 'remark',
];

const LONG_TEXT_COLS = new Set<string>([
  'invitation_field', 'request_reason', 'assign_reason', 'hq_opinion', 'note', 'remark',
]);

// ─── ReadCell (module-level) ──────────────────────────────────────────────
function ReadCell({ value, fieldKey }: { value: string | null; fieldKey: string }) {
  const isLong = LONG_TEXT_COLS.has(fieldKey);
  const display = value ?? '';
  return (
    <td
      className={`border border-gray-300 px-2 py-1 text-center ${isLong ? 'max-w-[160px] truncate overflow-hidden' : ''}`}
      title={isLong ? display : undefined}
    >
      {display}
    </td>
  );
}

// ─── EditableCell (module-level) ──────────────────────────────────────────
function EditableCell({
  rowId,
  fieldKey,
  initialValue,
  onSave,
}: {
  rowId: number;
  fieldKey: string;
  initialValue: string | null;
  onSave?: (id: number, fields: Record<string, string>) => Promise<void>;
}) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(initialValue ?? '');
  const [dirty, setDirty] = useState(false);
  const [saved, setSaved] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLong = LONG_TEXT_COLS.has(fieldKey);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const commitEdit = useCallback(async () => {
    setEditing(false);
    if (dirty && onSave) {
      await onSave(rowId, { [fieldKey]: value });
      setSaved(true);
      timerRef.current = setTimeout(() => setSaved(false), 500);
    }
  }, [dirty, onSave, rowId, fieldKey, value]);

  const handleDoubleClick = () => {
    setEditing(true);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setValue(e.target.value);
    setDirty(e.target.value !== (initialValue ?? ''));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      if (isLong && e.shiftKey) return; // allow newline in textarea
      commitEdit();
    }
  };

  let bgClass = '';
  if (saved) bgClass = 'bg-green-100';
  else if (dirty && !editing) bgClass = 'bg-yellow-100';

  if (editing) {
    return (
      <td className="border border-gray-300 px-1 py-0.5">
        {isLong ? (
          <textarea
            className="w-full text-xs"
            value={value}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onBlur={() => commitEdit()}
            autoFocus
          />
        ) : (
          <input
            type="text"
            className="w-full text-xs"
            value={value}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onBlur={() => commitEdit()}
            autoFocus
          />
        )}
      </td>
    );
  }

  const display = value || '';
  return (
    <td
      className={`border border-gray-300 px-2 py-1 text-center cursor-pointer ${bgClass} ${isLong ? 'max-w-[160px] truncate overflow-hidden' : ''}`}
      title={isLong ? display : undefined}
      onDoubleClick={handleDoubleClick}
    >
      {display}
    </td>
  );
}

// ─── TOHaejungTable ───────────────────────────────────────────────────────
export default function TOHaejungTable({ rows, editable, onSave }: TOHaejungTableProps) {
  return (
    <div className="overflow-x-auto w-full">
      <table className="min-w-max border-collapse text-xs whitespace-nowrap">
        <thead>
          {/* Row 1 */}
          <tr className="bg-blue-700 text-white">
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">소속대학</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">학과명</th>
            <th colSpan={2} className="border border-gray-300 px-2 py-1">교원확보율(2026.3.1기준)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">최근 3년간 신규임용자(&apos;23~&apos;26)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">최근 3년간 퇴직자(&apos;23~&apos;25)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">향후 정년퇴직예정자(&apos;25~&apos;28)</th>
            <th colSpan={4} className="border border-gray-300 px-2 py-1">요청</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">초빙분야</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">학과요청사유</th>
            <th colSpan={4} className="border border-gray-300 px-2 py-1">일반TO 배정(안)</th>
            <th colSpan={4} className="border border-gray-300 px-2 py-1">첨단학과신설 특별TO 배정(안)</th>
            <th colSpan={4} className="border border-gray-300 px-2 py-1">총장TO 배정(안)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">배정사유</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">본부 배정의견</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">BIGs</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">25년 TO신청(명)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">25년 TO배정(명)</th>
            <th colSpan={3} className="border border-gray-300 px-2 py-1">25년 채용결과(명)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">참고(2025학년도 채용경과 등)</th>
            <th rowSpan={2} className="border border-gray-300 px-2 py-1">비고(BK 및 대형과제)</th>
          </tr>
          {/* Row 2 */}
          <tr className="bg-blue-600 text-white">
            {/* 교원확보율 sub */}
            <th className="border border-gray-300 px-2 py-1">확보율</th>
            <th className="border border-gray-300 px-2 py-1">교원수</th>
            {/* 요청 sub */}
            <th className="border border-gray-300 px-2 py-1">일반</th>
            <th className="border border-gray-300 px-2 py-1">전담</th>
            <th className="border border-gray-300 px-2 py-1">外</th>
            <th className="border border-gray-300 px-2 py-1">계</th>
            {/* 일반TO sub */}
            <th className="border border-gray-300 px-2 py-1">일반</th>
            <th className="border border-gray-300 px-2 py-1">전담</th>
            <th className="border border-gray-300 px-2 py-1">外</th>
            <th className="border border-gray-300 px-2 py-1">계</th>
            {/* 첨단TO sub */}
            <th className="border border-gray-300 px-2 py-1">일반</th>
            <th className="border border-gray-300 px-2 py-1">전담</th>
            <th className="border border-gray-300 px-2 py-1">外</th>
            <th className="border border-gray-300 px-2 py-1">계</th>
            {/* 총장TO sub */}
            <th className="border border-gray-300 px-2 py-1">일반</th>
            <th className="border border-gray-300 px-2 py-1">전담</th>
            <th className="border border-gray-300 px-2 py-1">外</th>
            <th className="border border-gray-300 px-2 py-1">계</th>
            {/* 25년 채용결과 sub */}
            <th className="border border-gray-300 px-2 py-1">정시</th>
            <th className="border border-gray-300 px-2 py-1">상시</th>
            <th className="border border-gray-300 px-2 py-1">합계</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={35} className="border border-gray-300 px-4 py-8 text-center text-gray-500">
                데이터가 없습니다. 관리자 페이지에서 Excel을 업로드하세요.
              </td>
            </tr>
          ) : (
            rows.map((row, idx) => (
              <tr
                key={row.id}
                className={idx % 2 === 0 ? 'bg-white hover:bg-blue-50' : 'bg-gray-50 hover:bg-blue-50'}
              >
                {FIELD_KEYS.map((key) =>
                  editable ? (
                    <EditableCell
                      key={key}
                      rowId={row.id}
                      fieldKey={key}
                      initialValue={row[key] as string | null}
                      onSave={onSave}
                    />
                  ) : (
                    <ReadCell key={key} value={row[key] as string | null} fieldKey={key} />
                  )
                )}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
